using PROYECTO_MONGO_DOTNET.Models;
namespace PROYECTO_MONGO_DOTNET.Services;
public sealed class PermisoDAO(SqlContexto db):SqlDAO(db)
{
 public bool TienePermiso(string p,string o,PermisoAccion a=PermisoAccion.Ver){var col=a switch{PermisoAccion.Crear=>"PuedeCrear",PermisoAccion.Editar=>"PuedeEditar",PermisoAccion.Eliminar=>"PuedeEliminar",_=>"PuedeVer"};return Db.Escalar<int>($"SELECT COUNT(1) FROM app.PerfilOpcion WHERE CodigoPerfil=@P AND CodigoOpcion=@O AND FechaRetiro IS NULL AND {col}=1",new{P=Mayuscula(p),O=Mayuscula(o)})>0;}
 public List<PermisoPerfil> ListarPorPerfil(string p)=>Aplanar(Db.Consultar<PermisoPerfil>("SELECT o.Codigo CodigoOpcion,o.Descripcion DescripcionOpcion,o.CodigoPadre,o.Nivel,o.Orden,CAST(COALESCE(x.PuedeVer,0) AS bit) Ver,CAST(COALESCE(x.PuedeCrear,0) AS bit) Crear,CAST(COALESCE(x.PuedeEditar,0) AS bit) Editar,CAST(COALESCE(x.PuedeEliminar,0) AS bit) Eliminar FROM app.Opcion o LEFT JOIN app.PerfilOpcion x ON x.CodigoOpcion=o.Codigo AND x.CodigoPerfil=@P AND x.FechaRetiro IS NULL WHERE o.Estado='A' ORDER BY o.Orden,o.Descripcion",new{P=Mayuscula(p)}));
 public void GuardarPerfil(string p,IEnumerable<PermisoPerfil> permisos,string u){using var cn=Db.Abrir();using var tx=cn.BeginTransaction();try{Db.Ejecutar("UPDATE app.PerfilOpcion SET FechaRetiro=SYSUTCDATETIME(),ModificadoPor=@U WHERE CodigoPerfil=@P AND FechaRetiro IS NULL",new{P=Mayuscula(p),U=u},tx);foreach(var x in permisos.Where(x=>x.Ver||x.Crear||x.Editar||x.Eliminar))Db.Ejecutar("INSERT app.PerfilOpcion(CodigoPerfil,CodigoOpcion,PuedeVer,PuedeCrear,PuedeEditar,PuedeEliminar,FechaAsignacion,ModificadoPor) VALUES(@P,@O,@Ver,@Crear,@Editar,@Eliminar,SYSUTCDATETIME(),@U)",new{P=Mayuscula(p),O=Mayuscula(x.CodigoOpcion),x.Ver,x.Crear,x.Editar,x.Eliminar,U=u},tx);tx.Commit();}catch{tx.Rollback();throw;}}
 private static List<PermisoPerfil>Aplanar(List<PermisoPerfil> f){var pp=f.GroupBy(x=>x.CodigoPadre??"").ToDictionary(x=>x.Key,x=>x.OrderBy(y=>y.Orden).ThenBy(y=>y.DescripcionOpcion).ToList(),StringComparer.OrdinalIgnoreCase);var cod=f.Select(x=>x.CodigoOpcion).ToHashSet(StringComparer.OrdinalIgnoreCase);var r=new List<PermisoPerfil>();void A(PermisoPerfil x){r.Add(x);if(pp.TryGetValue(x.CodigoOpcion,out var hs))foreach(var h in hs)A(h);}foreach(var x in f.Where(x=>string.IsNullOrWhiteSpace(x.CodigoPadre)||!cod.Contains(x.CodigoPadre)).OrderBy(x=>x.Orden))A(x);return r;}
}
